create or replace function public.accept_shared_record(p_notification_id uuid,p_to_user_id uuid) returns jsonb language plpgsql security definer set search_path to '' as $$ declare v_notif public.team_notifications%rowtype; begin if auth.uid() is null or p_to_user_id is distinct from auth.uid() then raise exception 'Not authorized'; end if; select * into v_notif from public.team_notifications where id=p_notification_id and to_user_id=auth.uid() for update; if not found then raise exception 'Notification not found'; end if; if v_notif.accepted then raise exception 'Already accepted'; end if; update public.team_notifications set accepted=true,accepted_at=now(),read=true where id=p_notification_id and to_user_id=auth.uid(); return jsonb_build_object('ok',true,'record_type',v_notif.record_type,'record_id',v_notif.record_id); end; $$;
create or replace function public.create_team_for_user(p_name text,p_user_id uuid) returns json language plpgsql security definer set search_path to '' as $$ declare v_team public.teams; begin if auth.uid() is null or p_user_id is distinct from auth.uid() then raise exception 'Not authorized'; end if; if p_name is null or length(trim(p_name))=0 or length(trim(p_name))>100 then raise exception 'Valid team name is required'; end if; insert into public.teams(name) values(trim(p_name)) returning * into v_team; insert into public.team_members(team_id,user_id,role) values(v_team.id,auth.uid(),'admin'); return row_to_json(v_team); end; $$;
create or replace function public.current_team_id() returns uuid language plpgsql security definer set search_path to '' as $$ declare v_team_id uuid; begin if auth.uid() is null then return null; end if; select tm.team_id into v_team_id from public.team_members tm where tm.user_id=auth.uid() order by tm.joined_at limit 1; return v_team_id; end; $$;
create or replace function public.get_team_member_emails(p_team_id uuid) returns table(user_id uuid,role text,joined_at timestamptz,email text) language sql security definer set search_path to '' as $$ select tm.user_id,tm.role::text,tm.joined_at,u.email from public.team_members tm left join auth.users u on u.id=tm.user_id where tm.team_id=p_team_id and exists(select 1 from public.team_members me where me.team_id=p_team_id and me.user_id=auth.uid()) order by tm.joined_at asc; $$;
create or replace function public.join_team_by_code(p_invite_code text,p_user_id uuid) returns json language plpgsql security definer set search_path to '' as $$ declare v_team public.teams; begin if auth.uid() is null or p_user_id is distinct from auth.uid() then raise exception 'Not authorized'; end if; if p_invite_code is null or length(trim(p_invite_code))=0 or length(trim(p_invite_code))>100 then raise exception 'Invalid invite code'; end if; select * into v_team from public.teams where invite_code is not null and upper(invite_code)=upper(trim(p_invite_code)) limit 1; if not found then raise exception 'Invalid invite code'; end if; if exists(select 1 from public.team_members where team_id=v_team.id and user_id=auth.uid()) then raise exception 'Already a member of this team'; end if; insert into public.team_members(team_id,user_id,role) values(v_team.id,auth.uid(),'member'); return row_to_json(v_team); end; $$;
create or replace function public.notify_assignment(p_to_user_id uuid,p_from_user_id uuid,p_team_id uuid,p_record_type text,p_record_id uuid,p_record_title text,p_message text) returns void language plpgsql security definer set search_path to '' as $$ begin if auth.uid() is null or p_from_user_id is distinct from auth.uid() then raise exception 'Not authorized'; end if; if p_record_type not in ('lead','followup','client','contact','quote') then raise exception 'Invalid record type'; end if; if length(coalesce(p_record_title,''))>300 or length(coalesce(p_message,''))>2000 then raise exception 'Notification content is too long'; end if; if not exists(select 1 from public.team_members where team_id=p_team_id and user_id=auth.uid()) or not exists(select 1 from public.team_members where team_id=p_team_id and user_id=p_to_user_id) then raise exception 'Users must belong to the same team'; end if; insert into public.team_notifications(team_id,from_user_id,to_user_id,record_type,record_id,record_title,message) values(p_team_id,auth.uid(),p_to_user_id,p_record_type,p_record_id,p_record_title,p_message); end; $$;
create or replace function public.reassign_record(p_table text,p_record_id uuid,p_assigned_to_user_id uuid,p_assigned_to text) returns void language plpgsql security definer set search_path to '' as $$ declare v_allowed boolean;v_team_id uuid;begin if auth.uid() is null then raise exception 'Not authorized'; end if; if p_table not in ('clients','contacts','followups','leads','notes','equipment') then raise exception 'Invalid table'; end if; if length(coalesce(p_assigned_to,''))>200 then raise exception 'Assignment label is too long'; end if; execute format('select exists (select 1 from public.%I r where r.id=$1 and (r.user_id=$2 or r.assigned_to_user_id=$2 or (r.team_id is not null and exists (select 1 from public.team_members tm where tm.team_id=r.team_id and tm.user_id=$2))))',p_table) into v_allowed using p_record_id,auth.uid(); if not v_allowed then raise exception 'Not authorized for this record'; end if; execute format('select team_id from public.%I where id=$1',p_table) into v_team_id using p_record_id; if v_team_id is not null then if not exists(select 1 from public.team_members where team_id=v_team_id and user_id=auth.uid()) or not exists(select 1 from public.team_members where team_id=v_team_id and user_id=p_assigned_to_user_id) then raise exception 'Target user must belong to the same team'; end if; elsif p_assigned_to_user_id is distinct from auth.uid() then raise exception 'Cannot assign a personal record to another user'; end if; execute format('update public.%I set assigned_to_user_id=$1,assigned_to=$2 where id=$3',p_table) using p_assigned_to_user_id,p_assigned_to,p_record_id;end;$$;
